import{g as a,ad as e,r as n,A as t}from"./chunks/framework.BT7BGxmb.js";const u=JSON.parse('{"title":"Tailwind Setup","description":"","frontmatter":{},"headers":[],"relativePath":"docs/foundations/tailwind.md","filePath":"docs/foundations/tailwind.md","lastUpdated":1786274332000}'),o={name:"docs/foundations/tailwind.md"};function p(c,s,i,l,d,r){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="tailwind-setup" tabindex="-1">Tailwind Setup <a class="header-anchor" href="#tailwind-setup" aria-label="Permalink to “Tailwind Setup”">​</a></h1><p><code>frappe-ui</code> ships as a Tailwind v3 preset. Add it to your app&#39;s <code>tailwind.config.js</code>:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> preset</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">content</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  presets</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_11933w">preset</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  content</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_fjrnv8">...</span><span class="s_11933w">content</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./src/**/*.{vue,js,ts,jsx,tsx}</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>The preset sets <code>darkMode</code>, the integer spacing scale (<code>1</code>–<code>64</code>, filling the gaps in Tailwind&#39;s default scale), the <code>prose</code> / <code>prose-v3</code> typography safelist, and four plugins (<code>@tailwindcss/forms</code>, <code>@tailwindcss/typography</code>, the theme plugin, the Lucide icon plugin). That&#39;s the whole exported surface — a default export (the preset) and the named <code>content</code> export below.</p><h2 id="why-you-have-to-list-content-yourself" tabindex="-1">Why you have to list <code>content</code> yourself <a class="header-anchor" href="#why-you-have-to-list-content-yourself" aria-label="Permalink to “Why you have to list content yourself”">​</a></h2><p>Tailwind v3 does not merge a preset&#39;s <code>content</code> into your app&#39;s config — it only reads the top-level <code>content.files</code> array. A preset can ship <code>theme</code> and <code>plugins</code>, which do merge, but not <code>content</code>. This is a Tailwind v3 limitation, not a choice <code>frappe-ui</code> makes.</p><p>That means every app consuming <code>frappe-ui</code> has to know which of its source folders emit Tailwind classes and list them itself. Left hand-maintained, that list drifts: two apps on <code>frappe-ui@1.0.0-beta</code> only glob <code>src/components/**</code>, missing <code>src/molecules/</code> entirely — every utility class the editor and list molecules emit never gets compiled into those apps&#39; CSS. The exported list mirrors this repo&#39;s own <code>tailwind.config.js</code> <code>content</code> array, so the two can&#39;t drift apart from each other either.</p><h2 id="the-content-export" tabindex="-1">The <code>content</code> export <a class="header-anchor" href="#the-content-export" aria-label="Permalink to “The content export”">​</a></h2><p><code>frappe-ui/tailwind</code> exports the glob list it needs as <code>content</code>, so your <code>content</code> array becomes &quot;the library&#39;s globs, plus mine&quot; instead of a hand-copied path list:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">content</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">console</span><span class="s_1jjt6x">.</span><span class="s_indoxt">log</span><span class="s_13ahmt">(</span><span class="s_22m8k2">content</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1th9sy">// [</span></span>
<span class="line"><span class="s_1th9sy">//   &#39;.../frappe-ui/src/**/*.{vue,js,ts,jsx,tsx}&#39;,</span></span>
<span class="line"><span class="s_1th9sy">//   &#39;.../frappe-ui/icons/**/*.{vue,js,ts,jsx,tsx}&#39;,</span></span>
<span class="line"><span class="s_1th9sy">//   &#39;.../frappe-ui/experimental/SpriteIcons/**/*.{vue,js,ts,jsx,tsx}&#39;,</span></span>
<span class="line"><span class="s_1th9sy">// ]</span></span></code></pre></div><p>The rest of <code>experimental/</code> is not covered — it carries no stability promise. <code>SpriteIcons</code> is the one exception: it holds a previously supported surface (<code>Icon</code>, <code>IconPicker</code>, <code>spritePlugin</code>, moved out of <code>frappe-ui/icons</code>), so its classes stay compiled until it is removed.</p><p>The paths are resolved against wherever <code>frappe-ui</code> is actually installed (<code>node_modules</code>, a monorepo symlink, a local workspace checkout), so they work regardless of your app&#39;s working directory. When <code>frappe-ui</code> adds a new source directory that emits classes, bumping the dependency picks up the new glob automatically — you don&#39;t need to touch your <code>tailwind.config.js</code> again.</p>`,12)])])}const _=a(o,[["render",p]]);export{u as __pageData,_ as default};
